"use client";

import * as React from "react";
import { addDays, format } from "date-fns";
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  PanelLeftIcon,
  PanelRightIcon,
} from "lucide-react";

import { cn } from "@/lib/utils";
import { useCalendar, useCalendarConfig } from "@/components/calendar-provider";
import { Button } from "@/components/ui/button";
import { Kbd } from "@/components/ui/kbd";
import { Separator } from "@/components/ui/separator";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { ViewDropdown } from "@/components/view-dropdown";
import { AGENDA_DAYS } from "@/lib/event-utils";

import type { ViewType } from "@/components/calendar-types";

/** What previous and next move by in each view, for their labels */
const PERIOD_LABELS: Record<ViewType, string> = {
  day: "day",
  week: "week",
  month: "month",
  agenda: `${AGENDA_DAYS} days`,
};

interface CalendarHeaderProps {
  /** Whether the sidebar is open: its toggle's tooltip offers to close or open it */
  sidebarOpen?: boolean;
  /** Opens or closes the sidebar. The sidebar toggle shows only when given */
  onToggleSidebar?: () => void;
  /** Whether the context panel is open. Its toggle hides while it is */
  contextPanelOpen?: boolean;
  /** Opens or closes the context panel. The toggle shows only when given */
  onToggleContextPanel?: () => void;
  /** Shown before the view switcher on wide headers, e.g. the signed-in user's avatar */
  children?: React.ReactNode;
  className?: string;
}

/**
 * The live demo's header: the sidebar toggle, the month and year with the
 * period on screen, then the view switcher, today, previous and next, and
 * the context panel toggle. Reads the calendar from `useCalendar()`, so it
 * goes inside `CalendarProvider`; the panels are your app's, so their state
 * comes in as props.
 */
export function CalendarHeader({
  sidebarOpen = false,
  onToggleSidebar,
  contextPanelOpen = false,
  onToggleContextPanel,
  children,
  className,
}: CalendarHeaderProps) {
  const { monthName, year } = useCalendar();

  return (
    // Tooltips need a provider with Radix; a closer one (yours) still wins
    <TooltipProvider>
      <header
        className={cn(
          "@container/header bg-background sticky top-0 z-30 flex h-14 shrink-0 items-center gap-2",
          className,
        )}
      >
        <div className="flex min-w-0 flex-1 items-center gap-1 pl-2 @md/header:gap-2 @xl/header:px-4">
          {onToggleSidebar && (
            <>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="size-7 text-muted-foreground"
                    onClick={onToggleSidebar}
                  >
                    <PanelLeftIcon />
                    <span className="sr-only">Toggle Calendar Sidebar</span>
                  </Button>
                </TooltipTrigger>
                <TooltipContent side="bottom">
                  {sidebarOpen ? "Close" : "Open"} sidebar{" "}
                  <Kbd className="ml-1">⌘</Kbd> <Kbd>/</Kbd>
                </TooltipContent>
              </Tooltip>
              <Separator
                orientation="vertical"
                className="mr-2 hidden data-[orientation=vertical]:h-4 @md/header:block"
              />
            </>
          )}
          <h1 className="min-w-0 truncate text-sm @xs/header:text-base @xl/header:text-xl">
            {/* Narrow headers use the short month ("Sep"); en-US "MMMM" names abbreviate to their first three letters */}
            <span className="font-extrabold @md/header:hidden">
              {monthName.slice(0, 3)}
            </span>
            <span className="hidden font-extrabold @md/header:inline">
              {monthName}
            </span>{" "}
            <span className="font-extrabold">{year}</span>{" "}
            <CalendarPeriodLabel className="text-muted-foreground hidden text-xs @xl/header:inline" />
          </h1>
        </div>
        <div className="flex shrink-0 items-center gap-1 pr-2 @md/header:gap-2 @xl/header:px-4">
          {children && <div className="hidden @xl/header:flex">{children}</div>}
          <div className="hidden @xs/header:block">
            <CalendarViewSwitcher />
          </div>
          <CalendarNavigation buttonClassName="size-7 @2xs/header:size-8" />
          {onToggleContextPanel && !contextPanelOpen && (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="size-7 text-muted-foreground"
                  onClick={onToggleContextPanel}
                >
                  <PanelRightIcon />
                  <span className="sr-only">Toggle Navigation Sidebar</span>
                </Button>
              </TooltipTrigger>
              <TooltipContent side="bottom">
                Open context panel <Kbd className="ml-1">/</Kbd>
              </TooltipContent>
            </Tooltip>
          )}
        </div>
      </header>
    </TooltipProvider>
  );
}

interface CalendarPeriodLabelProps {
  className?: string;
}

/**
 * The period on screen, for beside the title: the day ("Thursday, Jun 4"),
 * the week number ("Week 23") or the agenda's range. Empty in month view,
 * where the title already says it.
 */
export function CalendarPeriodLabel({ className }: CalendarPeriodLabelProps) {
  const { view, currentDate, weekNumber } = useCalendar();
  const { locale } = useCalendarConfig();

  return (
    <span className={className}>
      {view === "day" && format(currentDate, "EEEE, MMM d", { locale })}
      {view === "week" && `Week ${weekNumber}`}
      {view === "agenda" &&
        `${format(currentDate, "MMM d", { locale })} – ${format(addDays(currentDate, AGENDA_DAYS - 1), "MMM d", { locale })}`}
    </span>
  );
}

/**
 * The view dropdown wired to the provider: day, week, month or agenda, the
 * number of days, and the weekend, declined event and week number settings
 */
export function CalendarViewSwitcher() {
  const {
    view,
    numberOfDays,
    viewSettings,
    switchView,
    setNumberOfDays,
    toggleWeekends,
    toggleDeclinedEvents,
    toggleWeekNumbers,
  } = useCalendar();

  return (
    <ViewDropdown
      view={view}
      numberOfDays={numberOfDays}
      viewSettings={viewSettings}
      onSwitchView={switchView}
      onSetNumberOfDays={setNumberOfDays}
      onToggleWeekends={toggleWeekends}
      onToggleDeclinedEvents={toggleDeclinedEvents}
      onToggleWeekNumbers={toggleWeekNumbers}
    />
  );
}

interface CalendarNavigationProps {
  /** Classes for the previous and next buttons, e.g. their size */
  buttonClassName?: string;
}

/** Today, then previous and next, labelled with the period they move by */
export function CalendarNavigation({
  buttonClassName,
}: CalendarNavigationProps) {
  const { view, goToToday, goToPrev, goToNext } = useCalendar();
  const periodLabel = PERIOD_LABELS[view];

  return (
    <>
      <Button
        variant="secondary"
        size="sm"
        className="px-2 @md/header:px-3"
        onClick={goToToday}
      >
        Today
      </Button>
      <div className="flex items-center">
        <Button
          variant="ghost"
          size="icon"
          className={cn("text-muted-foreground", buttonClassName)}
          onClick={goToPrev}
        >
          <ChevronLeftIcon className="size-4" />
          <span className="sr-only">Previous {periodLabel}</span>
        </Button>
        <Button
          variant="ghost"
          size="icon"
          className={cn("text-muted-foreground", buttonClassName)}
          onClick={goToNext}
        >
          <ChevronRightIcon className="size-4" />
          <span className="sr-only">Next {periodLabel}</span>
        </Button>
      </div>
    </>
  );
}

"use client";

import { CheckIcon, ChevronDownIcon } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Kbd, KbdGroup } from "@/components/ui/kbd";

import type { ViewSettings, ViewType } from "@/components/week-view-types";

/** Display labels for each view type */
const VIEW_LABELS: Record<ViewType, string> = {
  day: "Day",
  week: "Week",
  month: "Month",
  agenda: "Agenda",
};

/** View mode options with their shortcut labels */
const VIEW_OPTIONS: Array<{
  value: ViewType;
  label: string;
  shortcuts: Array<string>;
}> = [
  { value: "day", label: "Day", shortcuts: ["1", "or", "D"] },
  { value: "week", label: "Week", shortcuts: ["0", "or", "W"] },
  { value: "month", label: "Month", shortcuts: ["M"] },
  { value: "agenda", label: "Agenda", shortcuts: ["A"] },
];

/** Number-of-days options for the submenu */
const DAYS_OPTIONS = [2, 3, 4, 5, 6, 7, 8, 9] as const;

/** Views that hide the weekend when "Weekends" is off. The rest ignore it for now */
const WEEKENDS_SETTING_VIEWS: ViewType[] = ["month", "agenda"];

/** Views that draw week numbers when "Week numbers" is on. The rest ignore it for now */
const WEEK_NUMBERS_SETTING_VIEWS: ViewType[] = ["month"];

/**
 * Shortcut hints inside menu items drop the key-cap background. Classes
 * rather than a Kbd variant, so the file works with the stock shadcn/ui Kbd.
 */
const PLAIN_KBD_CLASS = "h-auto min-w-0 rounded-none bg-transparent px-0";

/** "Soon" badge of a setting the current view doesn't read yet, as in the command menu */
const SOON_BADGE = (
  <span className="bg-muted text-muted-foreground ml-auto rounded px-1.5 py-0.5 text-[10px] leading-none font-medium">
    Soon
  </span>
);

/**
 * A setting marked "Soon" stays disabled, but only its label and check dim:
 * the badge keeps its full strength. Both spellings of the variant, because
 * the Radix and Base UI styles of shadcn/ui write it differently.
 */
const SOON_ITEM_CLASS =
  "data-[disabled]:opacity-100 data-disabled:opacity-100 [&_svg]:opacity-50";

interface ViewDropdownProps {
  view: ViewType;
  numberOfDays: number;
  viewSettings: ViewSettings;
  onSwitchView: (view: ViewType) => void;
  onSetNumberOfDays: (count: number) => void;
  onToggleWeekends: () => void;
  onToggleDeclinedEvents: () => void;
  onToggleWeekNumbers: () => void;
}

export function ViewDropdown({
  view,
  numberOfDays,
  viewSettings,
  onSwitchView,
  onSetNumberOfDays,
  onToggleWeekends,
  onToggleDeclinedEvents,
  onToggleWeekNumbers,
}: ViewDropdownProps) {
  const weekendsSoon = !WEEKENDS_SETTING_VIEWS.includes(view);
  const weekNumbersSoon = !WEEK_NUMBERS_SETTING_VIEWS.includes(view);

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="secondary" size="sm" className="gap-1 px-3">
          {VIEW_LABELS[view]}
          <ChevronDownIcon className="size-4 text-muted-foreground" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" sideOffset={8} className="w-56">
        {VIEW_OPTIONS.map((option) => (
          <DropdownMenuItem
            key={option.value}
            onClick={() => onSwitchView(option.value)}
          >
            <CheckIcon
              className={cn(
                "size-4 shrink-0",
                view !== option.value && "invisible",
              )}
            />
            {option.label}
            <KbdGroup className="ml-auto">
              {option.shortcuts.map((s) =>
                s === "or" ? (
                  <span key={s} className="text-muted-foreground text-xs">
                    or
                  </span>
                ) : (
                  <Kbd key={s} className={PLAIN_KBD_CLASS}>
                    {s}
                  </Kbd>
                ),
              )}
            </KbdGroup>
          </DropdownMenuItem>
        ))}

        <DropdownMenuSeparator />

        {/* Number of days submenu */}
        <DropdownMenuSub>
          <DropdownMenuSubTrigger className="pl-8">
            Number of days
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent>
            {DAYS_OPTIONS.map((n) => (
              <DropdownMenuItem key={n} onClick={() => onSetNumberOfDays(n)}>
                <CheckIcon
                  className={cn(
                    "size-4 shrink-0",
                    numberOfDays !== n && "invisible",
                  )}
                />
                {n} days
                <Kbd className={cn(PLAIN_KBD_CLASS, "ml-auto")}>{n}</Kbd>
              </DropdownMenuItem>
            ))}
          </DropdownMenuSubContent>
        </DropdownMenuSub>

        <DropdownMenuSeparator />

        {/* View settings submenu */}
        <DropdownMenuSub>
          <DropdownMenuSubTrigger className="pl-8">
            View settings
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent className="w-56">
            {/* Day and week view don't hide the weekend yet */}
            <DropdownMenuCheckboxItem
              disabled={weekendsSoon}
              className={cn(weekendsSoon && SOON_ITEM_CLASS)}
              checked={viewSettings.showWeekends}
              onCheckedChange={() => onToggleWeekends()}
            >
              <span className={cn(weekendsSoon && "opacity-50")}>Weekends</span>
              {weekendsSoon ? (
                SOON_BADGE
              ) : (
                <KbdGroup className="ml-auto">
                  <Kbd className={PLAIN_KBD_CLASS}>shift</Kbd>
                  <Kbd className={PLAIN_KBD_CLASS}>&#8984;</Kbd>
                  <Kbd className={PLAIN_KBD_CLASS}>E</Kbd>
                </KbdGroup>
              )}
            </DropdownMenuCheckboxItem>

            {/* Nothing filters by this setting yet */}
            <DropdownMenuCheckboxItem
              disabled
              className={SOON_ITEM_CLASS}
              checked={viewSettings.showDeclinedEvents}
              onCheckedChange={() => onToggleDeclinedEvents()}
            >
              <span className="opacity-50">Declined events</span>
              {SOON_BADGE}
            </DropdownMenuCheckboxItem>

            {/* Only month view draws week numbers */}
            <DropdownMenuCheckboxItem
              disabled={weekNumbersSoon}
              className={cn(weekNumbersSoon && SOON_ITEM_CLASS)}
              checked={viewSettings.showWeekNumbers}
              onCheckedChange={() => onToggleWeekNumbers()}
            >
              <span className={cn(weekNumbersSoon && "opacity-50")}>
                Week numbers
              </span>
              {weekNumbersSoon && SOON_BADGE}
            </DropdownMenuCheckboxItem>
          </DropdownMenuSubContent>
        </DropdownMenuSub>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
